import React, { useState } from "react";
import "./Quiz.css";

const Quiz = () => {
  const question = "Which sorting algorithm uses divide and conquer?";
  const options = ["QuickSort", "BubbleSort", "SelectionSort", "InsertionSort"];
  const correctAnswer = "QuickSort";
  const [selected, setSelected] = useState(null);

  return (
    <div className="quiz-container">
      <h3>{question}</h3>
      {options.map((opt, index) => (
        <button
          key={index}
          className={selected === opt ? "selected" : ""}
          onClick={() => setSelected(opt)}
          disabled={selected !== null}
        >
          {opt}
        </button>
      ))}
    </div>
  );
};

export default Quiz;
